CREATE TABLE shared_comments ( id text PRIMARY KEY CHECK (trim(id) <> ''), object_ref text NOT NULL CHECK (trim(object_ref) <> ''), kind text NOT NULL CHECK (kind IN ('message', 'note', 'github')), author TEXT NOT NULL CHECK ( json_type(author) = 'object' AND coalesce(json_extract(author, '$.kind') IN ('drew', 'muse', 'agent'), 0) AND nullif(trim(json_extract(author, '$.id')), '') IS NOT NULL AND nullif(trim(json_extract(author, '$.label')), '') IS NOT NULL ), author_verified INTEGER NOT NULL DEFAULT 0, provenance text CHECK (provenance IN ('verified', 'asserted-legacy')), linked_identity TEXT CHECK ( linked_identity IS NULL OR ( json_type(linked_identity) = 'object' AND nullif(trim(json_extract(linked_identity, '$.source')), '') IS NOT NULL AND nullif(trim(json_extract(linked_identity, '$.id')), '') IS NOT NULL ) ), body text NOT NULL, created_at TEXT NOT NULL, triage_state text CHECK (triage_state IN ('new', 'triaged')), github_ref text CHECK (github_ref IS NULL OR (github_ref NOT GLOB '*[^A-Za-z0-9._/#-]*' AND github_ref NOT GLOB '*/*/*' AND github_ref NOT GLOB '*#*#*' AND instr(github_ref, '/') > 1 AND instr(substr(github_ref, instr(github_ref, '/') + 1), '#') > 1 AND length(substr(github_ref, instr(github_ref, '/') + instr(substr(github_ref, instr(github_ref, '/') + 1), '#') + 1)) >= 1 AND substr(github_ref, instr(github_ref, '/') + instr(substr(github_ref, instr(github_ref, '/') + 1), '#') + 1) NOT GLOB '*[^0-9]*')), github_state text CHECK (github_state IN ('pending', 'posted', 'failed')), github_url text, github_error text, github_failed_at TEXT, CONSTRAINT shared_comments_pending_github_ref_check CHECK ( kind <> 'github' OR github_state <> 'pending' OR github_ref IS NOT NULL ) );
CREATE INDEX shared_comments_object_created_idx ON shared_comments (object_ref, created_at);
